{{ 
  config(
    materialized = "incremental", 
    unique_key = "unique_id", 
    table_format = "iceberg", 
    external_volume = "ICEBERG_EXTERNAL_VOLUME",
    database = env_var('DBT_ENVIRONMENT') ~ '_MODELING',
    schema = env_var('DBT_ENVIRONMENT') ~ '_MODELING_GA4'
  ) 
}}

WITH events AS (

    SELECT *, PARSE_JSON(event_params_auto_flattened) AS parsed_params
    FROM {{ ref('stg_ga4__events') }}
    
    {% if is_incremental() %}
    WHERE ingestion_date > (
        SELECT IFNULL(MAX(ingestion_date), '1900-01-01')
        FROM {{ this }}
    )
    {% else %}
    WHERE ingestion_date > '1900-01-01'
    {% endif %}

)

